cd /home/user/rork-app/expo
APK=android/app/build/outputs/apk/release/app-release.apk
echo "=== APK details ==="
ls -la $APK
md5sum $APK
sha256sum $APK
APK_BYTES=$(wc -c < $APK)
echo "bytes=$APK_BYTES"

# Re-mint owner token if expired
if [ ! -s /tmp/owner_at ]; then
  curl -s -X POST https://api.ivxholding.com/api/ivx/owner-passwordless-login \
    -H "Content-Type: application/json" -d '{"email":"iperez4242@gmail.com"}' -o /tmp/login.json
  node -e "const d=JSON.parse(require('fs').readFileSync('/tmp/login.json','utf8')); require('fs').writeFileSync('/tmp/owner_at', d.accessToken);"
  echo "owner token re-minted"
else
  echo "owner token present"
fi

# Request fresh presign URL (prior one may have expired after 60s timeout)
OWNER_TOKEN=$(cat /tmp/owner_at)
echo ""
echo "=== Request FRESH presign URL for v1.4.23 ==="
curl -s -X POST https://api.ivxholding.com/api/ivx/apk/presign-upload \
  -H "Authorization: Bearer $OWNER_TOKEN" \
  -H "Content-Type: application/json" \
  -d '{"key":"apk/ivx-holdings-v1.4.23.apk","confirm":true,"confirmText":"CONFIRM_IVX_APK_UPLOAD"}' \
  -o /tmp/presign-v1.4.23.json
node -e "const d=JSON.parse(require('fs').readFileSync('/tmp/presign-v1.4.23.json','utf8')); console.log('status:',d.status,'publicUrl:',d.publicUrl,'expiresIn:',d.expiresInSeconds,'approvedBy:',d.approvedBy);"

echo ""
echo "=== Upload APK to S3 ==="
node <<'NODE'
const fs = require('fs');
const presign = JSON.parse(fs.readFileSync('/tmp/presign-v1.4.23.json','utf8'));
const apkPath = 'android/app/build/outputs/apk/release/app-release.apk';
const apk = fs.readFileSync(apkPath);
console.log('uploading', apk.length, 'bytes to S3...');
(async () => {
  const start = Date.now();
  const res = await fetch(presign.uploadUrl, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/vnd.android.package-archive' },
    body: apk
  });
  const elapsed = Date.now() - start;
  console.log('PUT HTTP', res.status, 'in', (elapsed/1000).toFixed(2)+'s');
  const text = await res.text();
  if (text) console.log('response body:', text.slice(0,200));
})();
NODE

